### Código Corrigido:
```php
<?php
// Inicialização da sessão
session_start();
// Garantir que o banco está conectado
$conn = new mysqli("localhost", "root", "", "db_name");
if ($conn->connect_error) {
    die("Erro de conexão: " . $conn->connect_error);
}

$error = "";
$stmt = null;

if ($_SERVER['REQUEST_METHOD'] == 'POST') {
    reset($GLOBALS['_REQUEST']); // Limpa variáveis POST anteriores

    // Validação e sanitização (não há necessidade de sanitização com prepared statements)
    $username = clean_input($_POST["username"]);
    $password = ($_POST["password"] ?? '');

    // Prep
    $stmt = $conn->prepare("SELECT id, `password` FROM admin_users WHERE `username` = ?");
    $stmt->bind_param("s", $username);

    try {
        $stmt->execute();
        $stmt->store_result();
        $stmt->bind_result($id, $hashed_password);
        $stmt->fetch();

        if ($stmt->num_rows > 0) {
            if (password_verify($password, $hashed_password)) {
                $_SESSION['admin_logged_in'] = true;
                $_SESSION['admin_user_id'] = $id;
                $error = "";
                echo "<p>Login bem-sucedido! Redirecionando para <a href=\"admin_store.php\">Admin Dashboard</a></p>";
                header('Location: admin_store.php');
                exit();
            } else {
                $error = "Erro de autenticação.";
            }
        } else {
            $error = "Erro de autenticação.";
        }
    } catch (Exception $e) {
        // Limpe conexão após erro
        $stmt->close();
        $conn->close();
        $error = "Erro de autenticação.";
    } finally {
        // Fecha conexão em todos os casos
        if ($stmt) {
            $stmt->close();
        }
        $conn->close();
    }
}

function clean_input($data) {
    // Remove caracteres inválidos e não ANSI
    $data = stripslashes($data);
    $data = htmlspecialchars($data, ENT_QUOTES, 'UTF-8');
    // Remove caracteres perigosos
    return filter_var($data, FILTER_SANITIZE_STRING);
}
?>

